#include <array>
#include <vector>
#include <cstddef>
#include <omp.h>

using std::size_t;

void countQuadrants(std::vector<Point> const& points, std::array<size_t, 4> &bins) {
    size_t q1 = 0, q2 = 0, q3 = 0, q4 = 0;

    // Quadrant order:
    // bins[0] = x > 0, y > 0
    // bins[1] = x < 0, y > 0
    // bins[2] = x < 0, y < 0
    // bins[3] = x > 0, y < 0
    // Points on either axis are ignored.
    #pragma omp parallel for reduction(+:q1, q2, q3, q4)
    for (std::size_t i = 0; i < points.size(); ++i) {
        const Point& p = points[i];

        if (p.x > 0.0) {
            if (p.y > 0.0) {
                ++q1;
            } else if (p.y < 0.0) {
                ++q4;
            }
        } else if (p.x < 0.0) {
            if (p.y > 0.0) {
                ++q2;
            } else if (p.y < 0.0) {
                ++q3;
            }
        }
    }

    bins[0] = q1;
    bins[1] = q2;
    bins[2] = q3;
    bins[3] = q4;
}
